 void manage(){if(goalTools==null){purposePicker();return;}select("목표 설정");goalTools.settings();}
 void purposePicker(){String[] names=new String[GoalRules.PRESETS.length];for(int n=0;n<names.length;n++){GoalRules.Preset p=GoalRules.PRESETS[n];names[n]=p.name+" · "+p.title;}new AlertDialog.Builder(a).setTitle("함께할 누비").setItems(names,(d,n)->agentGoals(GoalRules.PRESETS[n].id)).setNegativeButton("닫기",null).show();}
 void agentGoals(String agent){GoalRules.Preset p=GoalRules.preset(agent);List<JSONObject> goals=new ArrayList<>();List<String> names=new ArrayList<>();for(JSONObject g:a.store.goals())if(!GoalStore.fixture(g)&&agent.equals(g.optString("character"))){goals.add(g);names.add(g.optString("title"));}new AlertDialog.Builder(a).setTitle(p.name+" · 내 목표 "+goals.size()).setItems(names.toArray(new String[0]),(d,n)->{c.switchConversation(goals.get(n).optString("id"),"");}).setPositiveButton("새 목표",(d,n)->createGoalFor(agent,"")).setNegativeButton("닫기",null).show();}
 void createGoalFor(String agent,String prompt){EditText title=new EditText(a);title.setHint("이루고 싶은 목표");new AlertDialog.Builder(a).setTitle(GoalRules.preset(agent).name+"의 새 목표").setView(title).setNegativeButton("취소",null).setPositiveButton("만들기",(d,n)->{String value=title.getText().toString().trim();if(value.isEmpty()||value.length()>100){a.toast("목표를 1~100자로 적어주세요.");return;}GoalRules.Preset p=GoalRules.preset(agent);JSONObject g=a.store.create(agent,value,p.topic,0);c.switchConversation(g.optString("id"),"");if(!prompt.isEmpty())c.draft(prompt);}).show();}
 void runActions(){JSONObject run=a.runs.active();if(run==null)return;new AlertDialog.Builder(a).setTitle("진행 중인 작업").setMessage(CompanionCards.state(run.optString("state"))+"\n"+run.optString("text")+"\n"+run.optString("detail")).setPositiveButton("대화로 이동",(d,w)->c.switchConversation(run.optString("goalId"),run.optString("conversationId"))).setNeutralButton("결과 재확인",(d,w)->a.runs.retryStatus()).setNegativeButton("중지 요청",(d,w)->a.runs.cancel()).show();}
