 void conversations(){if(c.goalId.isEmpty()){purposePicker();return;}List<JSONObject> rows=a.store.workspace("conversations",c.goalId);String[] names=new String[rows.size()];for(int n=0;n<names.length;n++)names[n]=rows.get(n).optString("title");new AlertDialog.Builder(a).setTitle(c.goalTitle()+" · 대화").setItems(names,(d,n)->c.switchConversation(c.goalId,rows.get(n).optString("id"))).setPositiveButton("새 대화",(d,n)->c.newConversation()).setNeutralButton("이름 수정",(d,n)->{EditText title=new EditText(a);title.setText(a.store.workspaceRow("conversations",c.conversationId).optString("title"));new AlertDialog.Builder(a).setTitle("대화 이름").setView(title).setPositiveButton("저장",(x,y)->{try{a.store.renameConversation(c.conversationId,title.getText().toString());}catch(Exception e){a.toast("1~100자로 적어주세요.");}}).setNegativeButton("취소",null).show();}).setNegativeButton("닫기",null).show();}
