 void template(String prompt,String agent){List<JSONObject> goals=new ArrayList<>();List<String> names=new ArrayList<>();for(JSONObject g:a.store.goals())if(!GoalStore.fixture(g)&&g.optString("character").equals(agent)){goals.add(g);names.add(g.optString("title"));}new AlertDialog.Builder(a).setTitle(GoalRules.preset(agent).name+" · 어느 목표에 맡길까요?").setItems(names.toArray(new String[0]),(d,n)->{c.switchConversation(goals.get(n).optString("id"),"");c.draft(prompt);}).setPositiveButton("새 목표",(d,n)->createGoalFor(agent,prompt)).setNegativeButton("취소",null).show();}
 void buildSidebar(){buildSidebar(sidebar);}
 void buildSidebar(LinearLayout sidebar){LinearLayout brand=new LinearLayout(a);brand.setGravity(Gravity.CENTER_VERTICAL);brand.addView(text("누비",23,true),new LinearLayout.LayoutParams(0,dp(60),1));View search=icon("search","대화 검색",()->sidebarAction(sidebar,this::searchConversations),false);search.setBackgroundColor(Color.TRANSPARENT);brand.addView(search,new LinearLayout.LayoutParams(dp(40),dp(40)));sidebar.addView(brand);sidebar.addView(button("시연 스튜디오",()->a.startActivity(new Intent(a,InvestorDemoActivity.class))));View spacer=new View(a);sidebar.addView(spacer,new LinearLayout.LayoutParams(-1,0));String[] labels=(BuildConfig.HOME_STYLE==5||BuildConfig.HOME_STYLE==6)?new String[]{"홈","대화","둘러보기","보관함","나의 누비"}:BuildConfig.HOME_STYLE>0?new String[]{"홈","대화","친구","둘러보기","보관함","나의 누비"}:new String[]{"대화","친구","둘러보기","보관함","나의 누비"},pages=(BuildConfig.HOME_STYLE==5||BuildConfig.HOME_STYLE==6)?new String[]{"홈","대화","탐색","작업","내 정보"}:BuildConfig.HOME_STYLE>0?new String[]{"홈","대화","친구","탐색","작업","내 정보"}:new String[]{"대화","친구","탐색","작업","내 정보"},icons=(BuildConfig.HOME_STYLE==5||BuildConfig.HOME_STYLE==6)?new String[]{"compass","chat","compass","tray","person"}:BuildConfig.HOME_STYLE>0?new String[]{"compass","chat","friends","compass","tray","person"}:new String[]{"chat","friends","compass","tray","person"};for(int i=0;i<labels.length;i++){String next=BuildConfig.HOME_STYLE==6&&pages[i].equals("대화")?"누비톡":pages[i];LinearLayout row=new LinearLayout(a);row.setGravity(Gravity.CENTER_VERTICAL);row.setPadding(dp(10),0,dp(10),0);row.setTag(next);row.addView(new Glyph(a,icons[i],false),new LinearLayout.LayoutParams(dp(28),dp(28)));TextView label=text(labels[i],16,true);LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-2,-2);lp.leftMargin=dp(12);row.addView(label,lp);row.setContentDescription(labels[i]);row.setOnClickListener(v->sidebarAction(sidebar,()->select(next)));sidebar.addView(row,Ui.match(a,48,0));}TextView campusSection=text("학교생활",12,false);campusSection.setTextColor(MUTED);sidebar.addView(campusSection,Ui.match(a,-2,12));for(String campusPage:new String[]{"학교 시작하기"}){TextView campusLink=button(campusPage,()->sidebarAction(sidebar,()->select(campusPage)));campusLink.setGravity(Gravity.CENTER_VERTICAL);campusLink.setBackgroundColor(WHITE);campusLink.setContentDescription(campusPage);sidebar.addView(campusLink,Ui.match(a,40,0));}View line=new View(a);line.setBackgroundColor(0xffeeeeee);sidebar.addView(line,Ui.match(a,1,22));TextView section=text("최근 대화",13,false);section.setTextColor(MUTED);sidebar.addView(section);ScrollView goals=new ScrollView(a);LinearLayout list=c.box(WHITE,0);list.addView(button("+ 새 대화",()->sidebarAction(sidebar,c::newConversation)));list.addView(button("목표 보기",()->sidebarAction(sidebar,()->{if(c.goalId.isEmpty())purposePicker();else select("목표 보기");})));int shown=0;for(JSONObject conversation:a.store.workspace("conversations",null)){JSONObject goal=a.store.goal(conversation.optString("goalId"));if(GoalStore.fixture(goal))continue;if(shown++>=8)break;TextView item=text(conversation.optString("title")+"\n"+goal.optString("title"),14,false);item.setPadding(dp(8),dp(12),dp(8),dp(12));item.setOnClickListener(v->sidebarAction(sidebar,()->c.switchConversation(goal.optString("id"),conversation.optString("id"))));list.addView(item);}goals.addView(list);sidebar.addView(goals,new LinearLayout.LayoutParams(-1,-2));}
