 void searchConversations(){EditText query=new EditText(a);query.setHint("대화 제목·내용 검색");new AlertDialog.Builder(a).setTitle("대화 검색").setView(query).setPositiveButton("검색",(d,w)->{String key=query.getText().toString().trim();List<String> names=new ArrayList<>();List<JSONObject> rows=new ArrayList<>();for(JSONObject row:a.store.workspace("conversations",null)){JSONObject g=a.store.goal(row.optString("goalId"));if(GoalStore.fixture(g))continue;if(row.optString("title").contains(key)||row.optString("messages").contains(key)){rows.add(row);names.add(row.optString("title")+" · "+g.optString("title"));}}if(rows.isEmpty()){a.toast("검색 결과가 없어요.");return;}new AlertDialog.Builder(a).setTitle("검색 결과").setItems(names.toArray(new String[0]),(x,n)->c.switchConversation(rows.get(n).optString("goalId"),rows.get(n).optString("id"))).setNegativeButton("닫기",null).show();}).setNegativeButton("취소",null).show();}

 JSONArray latestSteps(){if(c.running||c.submitting)return c.steps;for(int n=c.history.length()-1;n>=0;n--){JSONObject m=c.history.optJSONObject(n);if(m!=null&&m.optString("role").equals("assistant")){JSONArray steps=m.optJSONArray("steps");return steps==null?new JSONArray():steps;}}return new JSONArray();}
 List<JSONObject> documents(){List<JSONObject> docs=new ArrayList<>();for(int n=c.history.length()-1;n>=0;n--){JSONObject m=c.history.optJSONObject(n);JSONObject d=m==null?null:m.optJSONObject("document");if(d!=null)docs.add(d);}return docs;}
 static final class Glyph extends View {
  final Paint p=new Paint(3);final String kind;final boolean fill;
  Glyph(Context c,String kind,boolean fill){super(c);this.kind=kind;this.fill=fill;}
  protected void onDraw(Canvas canvas){super.onDraw(canvas);canvas.save();canvas.translate(getWidth()/2f,getHeight()/2f);float s=Math.min(getWidth(),getHeight())/32f;canvas.scale(s,s);p.setColor(INK);p.setStrokeWidth(1.7f);p.setStyle(Paint.Style.STROKE);p.setStrokeCap(Paint.Cap.ROUND);switch(kind){
   case "documents":canvas.drawRoundRect(-10,-5,2,10,3,3,p);canvas.drawRoundRect(-5,-10,8,6,3,3,p);canvas.drawLine(2,-10,8,-4,p);canvas.drawLine(2,-10,2,-4,p);canvas.drawLine(2,-4,8,-4,p);break;
   case "search":canvas.drawCircle(-2,-2,6,p);canvas.drawLine(3,3,9,9,p);break;
   case "menu":canvas.drawLine(-6,-3,6,-3,p);canvas.drawLine(-6,3,6,3,p);break;
   case "plus":canvas.drawLine(-6,0,6,0,p);canvas.drawLine(0,-6,0,6,p);break;
   case "chat":p.setStyle(Paint.Style.FILL);canvas.drawOval(-9,-8,9,6,p);Path tail=new Path();tail.moveTo(-5,4);tail.lineTo(-7,9);tail.lineTo(1,5);canvas.drawPath(tail,p);break;
   case "compass":canvas.drawCircle(0,0,9,p);Path arrow=new Path();arrow.moveTo(-4,4);arrow.lineTo(1,-2);arrow.lineTo(4,-4);arrow.lineTo(2,2);arrow.close();canvas.drawPath(arrow,p);break;
   case "tray":canvas.drawRoundRect(-8,-2,8,8,2,2,p);canvas.drawLine(-8,-2,-4,-8,p);canvas.drawLine(-4,-8,4,-8,p);canvas.drawLine(4,-8,8,-2,p);canvas.drawLine(-3,3,3,3,p);break;
   default:canvas.drawCircle(0,-5,4,p);canvas.drawRoundRect(-8,2,8,9,4,4,p);
  }canvas.restore();}
 }
